namespace FCG.Games.Domain.Entities;
public sealed class Game{private Game(){}public int Id{get;private set;}public string Name{get;private set;}=string.Empty;public string Genre{get;private set;}=string.Empty;public decimal Price{get;private set;}public bool Active{get;private set;}=true;public DateTime CreatedAtUtc{get;private set;}
public static Game Create(string name,string genre,decimal price){if(string.IsNullOrWhiteSpace(name))throw new ArgumentException("Nome é obrigatório.");if(price<0)throw new ArgumentException("Preço não pode ser negativo.");return new(){Name=name.Trim(),Genre=genre.Trim(),Price=price,CreatedAtUtc=DateTime.UtcNow};}public void Update(string n,string g,decimal p){if(p<0)throw new ArgumentException("Preço inválido.");Name=n.Trim();Genre=g.Trim();Price=p;}public void Deactivate()=>Active=false;}
